package com.lqq.supportflow.conversation.infrastructure.persistence;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.baomidou.mybatisplus.core.conditions.update.UpdateWrapper; import com.lqq.supportflow.conversation.domain.*; import com.lqq.supportflow.shared.ConflictException; import java.time.Instant; import org.springframework.stereotype.Component;
@Component public class MyBatisConversationAdapter implements ConversationPort { private final ConversationMapper conversations; private final ConversationMessageMapper messages; private final GenerationMapper generations; public MyBatisConversationAdapter(ConversationMapper conversations,ConversationMessageMapper messages,GenerationMapper generations){this.conversations=conversations;this.messages=messages;this.generations=generations;} public Conversation create(Long tenantId,Long customerId){Instant now=Instant.now();ConversationEntity entity=new ConversationEntity();entity.tenantId=tenantId;entity.customerId=customerId;entity.status=ConversationStatus.AI_ACTIVE.name();entity.createdAt=now;entity.updatedAt=now;conversations.insert(entity);return new Conversation(entity.id,ConversationStatus.AI_ACTIVE);} public boolean belongsTo(Long tenantId,Long customerId,Long conversationId){return conversations.exists(new QueryWrapper<ConversationEntity>().eq("id",conversationId).eq("tenant_id",tenantId).eq("customer_id",customerId));} public boolean ownsGeneration(Long tenantId,Long customerId,Long generationId){GenerationEntity generation=generations.selectOne(new QueryWrapper<GenerationEntity>().eq("id",generationId).eq("tenant_id",tenantId));return generation!=null&&belongsTo(tenantId,customerId,generation.conversationId);} public Generation submit(Long tenantId,Long conversationId,String content,String idempotencyKey){ConversationMessageEntity existing=messages.selectOne(new QueryWrapper<ConversationMessageEntity>().eq("tenant_id",tenantId).eq("conversation_id",conversationId).eq("idempotency_key",idempotencyKey));if(existing!=null){GenerationEntity generation=generations.selectById(existing.generationId);return new Generation(generation.id,generation.conversationId,GenerationStatus.valueOf(generation.status));}Instant now=Instant.now();ConversationMessageEntity message=new ConversationMessageEntity();message.tenantId=tenantId;message.conversationId=conversationId;message.senderType="CUSTOMER";message.content=content;message.idempotencyKey=idempotencyKey;message.createdAt=now;messages.insert(message);GenerationEntity generation=new GenerationEntity();generation.tenantId=tenantId;generation.conversationId=conversationId;generation.userMessageId=message.id;generation.status=GenerationStatus.QUEUED.name();generation.createdAt=now;generation.updatedAt=now;generations.insert(generation);messages.update(new ConversationMessageEntity(),new UpdateWrapper<ConversationMessageEntity>().eq("id",message.id).set("generation_id",generation.id));return new Generation(generation.id,conversationId,GenerationStatus.QUEUED);}}
